def test_groups_words_by_length_and_preserves_order():
    words = ["pear", "fig", "plum", "fig", "kiwi", "date"]
    assert bucket_by_length(words) == {
        3: ["fig", "fig"],
        4: ["pear", "plum", "kiwi", "date"],
    }


def test_empty_input_returns_empty_dictionary():
    assert bucket_by_length([]) == {}


def test_empty_strings_belong_to_zero_and_order_is_preserved():
    words = ["", "a", "", "bb", "a", ""]
    assert bucket_by_length(words) == {0: ["", "", ""], 1: ["a", "a"], 2: ["bb"]}


def test_unicode_strings_are_bucketed_by_length():
    words = ["é", "ab", "中", "éé"]
    assert bucket_by_length(words) == {1: ["é", "中"], 2: ["ab", "éé"]}
"}

